const state={day:'day',date:'2026-09-18',comparison:'mom',point:null};
const iso=d=>d.toISOString().slice(0,10),parseDate=v=>new Date(v+'T00:00:00Z');
const shiftDate=(v,n)=>{const d=parseDate(v);d.setUTCDate(d.getUTCDate()+n);return iso(d)};
const validDate=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(parseDate(v).getTime())&&iso(parseDate(v))===v;
function dateRange(){const d=parseDate(state.date);if(state.day==='week'){const start=shiftDate(state.date,-((d.getUTCDay()+6)%7));return {start,end:shiftDate(start,6)}}if(state.day==='month')return {start:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1))),end:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)))};return {start:state.date,end:state.date}}
const days=()=>Math.round((parseDate(dateRange().end)-parseDate(dateRange().start))/86400000)+1;
const monthDays=()=>new Date(Date.UTC(parseDate(state.date).getUTCFullYear(),parseDate(state.date).getUTCMonth()+1,0)).getUTCDate();
function compareRange(kind=state.comparison){const r=dateRange(),d=parseDate(r.start);if(kind==='yoy'){const back=v=>{const t=parseDate(v),year=t.getUTCFullYear()-1,month=t.getUTCMonth(),day=Math.min(t.getUTCDate(),new Date(Date.UTC(year,month+1,0)).getUTCDate());return iso(new Date(Date.UTC(year,month,day)))};return {start:back(r.start),end:back(r.end)}}if(state.day==='month')return {start:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-1,1))),end:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),0)))};const offset=state.day==='week'?7:1;return {start:shiftDate(r.start,-offset),end:shiftDate(r.end,-offset)}}
const rangeText=r=>r.start+' ～ '+r.end;
const money=n=>Math.round(n).toLocaleString('zh-CN');
const signed=n=>(n>0?'+':'')+n.toFixed(1);
const flow=n=>n*days();
const metricList=[];const metrics={};
function add(id,name,value,unit,options={}){const m={id,name,value,unit,decimals:0,kind:'stock',mom:.024,yoy:.086,...options};metrics[id]=m;metricList.push(m);return m}
const current=m=>typeof m.value==='function'?m.value():m.value;
function previous(m,kind=state.comparison){if(m[kind+'Value']!==undefined)return typeof m[kind+'Value']==='function'?m[kind+'Value']():m[kind+'Value'];const v=m.kind==='rate'?current(m)-m[kind]:current(m)/(1+m[kind]);return m.kind==='stock'&&['人','家'].includes(m.unit)?Math.round(v):v}
function fmt(n,m,short=true){if(m.unit==='%'||m.unit==='月'||m.unit==='元/工时'||m.unit==='元/㎡')return n.toLocaleString('zh-CN',{minimumFractionDigits:m.decimals,maximumFractionDigits:m.decimals});if(short&&Math.abs(n)>=100000000)return (n/100000000).toFixed(2);if(short&&Math.abs(n)>=10000)return (n/10000).toFixed(m.unit==='人天'?1:2).replace(/\.00$/,'');return n.toLocaleString('zh-CN',{maximumFractionDigits:m.decimals})}
function unit(m,n=current(m),short=true){return short&&Math.abs(n)>=100000000?'亿'+m.unit:short&&Math.abs(n)>=10000?'万'+m.unit:m.unit}
const owners=[['direct','直营',210],['regulated','监管',86],['managed','托管',65],['cofound','和创',38]];
add('stores','在营门店',399,'家',{momValue:391,yoyValue:368,formula:'期末处于营业状态的门店数。',drivers:['新开门店','恢复营业','闭店及暂停营业']});
for(const [id,name,n] of owners)add(id,name+'门店',n,'家',{momValue:{direct:205,regulated:84,managed:64,cofound:38}[id],yoyValue:{direct:195,regulated:80,managed:60,cofound:33}[id],parent:'stores',formula:name+'模式下的在营门店数。',drivers:['新增门店','模式转入','退出及转出']});
add('building','在建门店',15,'家',{momValue:18,yoyValue:12,formula:'已立项、尚未开业的门店数。',drivers:['新立项','已开业转出','暂停项目']});
add('area','坪效',()=>2250*days()/monthDays(),'元/㎡',{kind:'flow',decimals:1,formula:'月坪效基准 2,250 元/㎡；日、周按所选月天数折算，跨月周以选定日期所在月为基准。演示折算，不代表实测逐日坪效。',drivers:['实收变化','营业面积变化']});
add('fulltime','正式工',25900,'人',{momValue:25380,yoyValue:23800,formula:'期末在岗正式工人数，不含小时工。',drivers:['新入职','离职','调入调出净额']});
add('hourly','小时工',()=>90000*days()/monthDays(),'人天',{kind:'flow',mom:.036,yoy:.12,formula:'小时工实际出勤折算人天；月基准90,000人天，日周按月天数折算。',drivers:['在岗小时工数量','人均出勤天数']});
add('efficiency','人效',170.9,'元/工时',{decimals:1,formula:'所选周期实收 ÷ 有效总工时。人员存量与有效工时为不同统计口径。',drivers:['实收变化','有效工时变化']});
add('members','累计会员',9920000,'人',{mom:.018,yoy:.18,formula:'截至期末累计去重会员数。',drivers:['新增注册','注销及去重']});
add('active','近3月活跃会员',5660000,'人',{mom:.026,yoy:.13,formula:'截至期末向前滚动3个月内，有至少一次有效消费的去重会员数。',drivers:['持续活跃','回流会员','流失会员']});
add('activeRate','活跃会员占比',()=>566/992*100,'%',{kind:'rate',decimals:1,mom:.5,yoy:-2.5,formula:'近3月活跃会员数 ÷ 累计会员数。',drivers:['活跃会员数变化','累计会员数变化']});
add('cash','现金安全',9.2,'月',{decimals:1,mom:.034,yoy:.123,target:6,caption:'存活能力',formula:'可用现金 ÷ 月均净现金支出。演示可用现金920万元、月均净支出100万元。',drivers:['可用现金变化','月均净支出变化']});
add('sameStore','同店营收',-1.2,'%',{kind:'rate',decimals:1,mom:-.5,yoy:-.7,target:0,caption:'维持能力',formula:'持续经营且可比门店的实收增长率；对比期间门店集合保持一致。',drivers:['堂食贡献','外卖贡献']});
add('profitGrowth','利润增速',2.1,'%',{kind:'rate',decimals:1,mom:-.6,yoy:.8,target:0,caption:'运营能力',formula:'（本期预算利润－环比期间预算利润）÷ 环比期间预算利润。',drivers:['实收贡献','食材成本贡献','人工与其他费用贡献']});
add('opening','开店成功',83,'%',{kind:'rate',decimals:0,mom:1.2,yoy:5,target:80,caption:'复制能力',formula:'观察期内达到预设经营目标的新店 ÷ 已完成观察期的新店。演示83/100家。',drivers:['达到目标的新店','观察期门店基数']});
const quadrants=[['problem','问题门店',31,'低利润 + 低得分，双差','red',3,6],['hidden','隐患门店',57,'高利润 + 低得分，利润下滑先兆','orange',-4,9],['potential','潜力门店',74,'低利润 + 高得分，结构性问题','blue',-2,-11],['benchmark','标杆门店',40,'高利润 + 高得分，双优头部','green',2,6],['unrated','待评估门店',197,'尚未满足利润与评分双维评估条件','muted',9,21]];
for(const [id,name,n,desc,color,mo,yo] of quadrants)add(id,name,n,'家',{momValue:n-mo,yoyValue:n-yo,caption:desc,color,lower:['problem','hidden','potential','unrated'].includes(id),formula:'按利润水平与巡店得分分类。演示阈值：利润率10%、巡店得分80分；四类互斥，未评估单列。',drivers:['从其他类别转入','转出至其他类别','新纳入及退出评估']});
add('target','目标实收',()=>flow(330000),'元',{kind:'flow',formula:'所选周期营业实收预算目标。',drivers:['同店目标调整','新店目标增加','退出门店目标减少']});
add('receipt','实际实收',()=>flow(300000),'元',{kind:'flow',momValue:()=>flow(330000),yoyValue:()=>flow(303600),formula:'净优惠及退款后的已完成交易实收；储值充值不计入营业实收。堂食=客单价×客流；外卖=单均价×订单数。',drivers:['堂食客流','堂食客单价','外卖订单数','外卖单均价']});
add('attainment','实收达成率',()=>current(metrics.receipt)/current(metrics.target)*100,'%',{kind:'rate',decimals:1,mom:-4.1,yoy:-2.4,target:100,formula:'实际实收 ÷ 目标实收。',drivers:['实际实收变化','预算目标变化']});
const payments=[['payGroup','美团团购',.545],['payDouyin','抖音券',.213],['payWechat','微信支付',.112],['payOther','其他',.049],['payMeituan','美团外卖',.035],['payAlipay','支付宝支付',.017],['payEle','饿了么',.027],['payVoucher','交通券',.002],['payCash','现金',0]];
for(const [id,name,share] of payments)add(id,name,()=>current(metrics.receipt)*share,'元',{kind:'flow',share,formula:'按收款方式归类的交易实收，每笔仅归属一种支付类型；不等同堂食/外卖履约渠道。',drivers:['支付笔数变化','每笔实收变化']});
const attraction=[['discount','分时分层优惠',.26],['ip','创始人IP',.12],['community','社区共创＋社交裂变',.18],['popular','爆品',.18],['newProduct','新品',.09],['delivery','外卖',.17]];
for(const [id,name,share] of attraction)add(id,name,()=>Math.round(flow(12000)*share),'人次',{kind:'flow',share,mom:.025+(share-.1),formula:'以可识别到店/访问为流量口径，按最后有效触点唯一归因；堂食与外卖访问不重复计入同次流量。流量占比=该来源流量÷全部已归因流量。',drivers:['触达人数变化','到访转化率变化']});
Object.assign(metrics.delivery,{unit:'单',formula:'按已归因的外卖订单统计，单位为单；数值与来源占比为演示数据。',drivers:['下单人数变化','人均订单数变化']});
add('traffic','已归因总流量',()=>flow(12000),'人次',{kind:'flow',formula:'已识别来源的有效访问总人次，按最后有效触点去重归因。',drivers:['付费及优惠流量','内容与社交流量','商品及外卖流量']});
const costs=[['food','食材成本',.34],['labor','预算人工成本',.24],['fixed','预算不可控费用',.16],['energy','预算能源费用',.035],['hygiene','预算卫生防疫和运输费',.012],['packaging','预算包装费',.018],['other','预算其他费',.025]];
const priorProfit=()=>flow(51000)/1.021;
for(const [id,name,share] of costs)add(id,name,()=>current(metrics.receipt)*share,'元',{kind:'flow',lower:true,share,momValue:()=>(flow(330000)-priorProfit())*share/.83,yoyValue:()=>previous(metrics.receipt,'yoy')*share*1.015,formula:(id==='food'?'期内食材耗用成本':'按预算规则分摊至所选期间的费用')+'；占实收比例=本项金额÷实际实收。预算数据不等同财务结账结果。',drivers:['经营规模变化','单位成本/费率变化']});
add('profit','预算利润',()=>current(metrics.receipt)-costs.reduce((n,[id])=>n+current(metrics[id]),0),'元',{kind:'flow',momValue:priorProfit,yoyValue:()=>previous(metrics.receipt,'yoy')-costs.reduce((n,[id])=>n+previous(metrics[id],'yoy'),0),formula:'实收－食材成本－预算人工－预算不可控费用－预算能源－预算卫生防疫和运输－预算包装－预算其他费用。',drivers:['实收变化',...costs.map(x=>x[1]+'变化')]});
for(const id of ['receipt','target','profit',...costs.map(x=>x[0])])metrics[id].sameStore=true;
for(const id of [...payments.map(x=>x[0]),...attraction.map(x=>x[0]),...costs.map(x=>x[0]),'profit']){const base=metrics[id],denominator=attraction.some(x=>x[0]===id)?'traffic':'receipt';add(id+'Share',base.name+'占比',()=>current(base)/current(metrics[denominator])*100,'%',{kind:'rate',decimals:1,base:id,denominator,lower:base.lower,sameStore:base.sameStore,momValue:()=>previous(base,'mom')/previous(metrics[denominator],'mom')*100,yoyValue:()=>previous(base,'yoy')/previous(metrics[denominator],'yoy')*100,formula:base.name+' ÷ '+metrics[denominator].name+'。归因影响以百分点展示。',drivers:['分子变化','分母变化']});base.shareMetric=id+'Share'}

const regions=['华东市场','华南市场','华中市场','华北市场','西南市场','西北市场'];
const route=()=>location.hash.slice(1)||'home';
function persist(){history.replaceState({filters:{...state},scroll:window.scrollY,depth:history.state?.depth||0},'')}
function go(id){persist();state.point=null;history.pushState({filters:{...state},scroll:0,depth:(history.state?.depth||0)+1},'','#'+id);render();window.scrollTo(0,0)}
function comparison(m,type='mom'){const delta=current(m)-previous(m,type),v=m.kind==='rate'?delta:previous(m,type)===0?0:delta/Math.abs(previous(m,type))*100;const bad=m.lower?v>0:v<0;return `<span class="${bad?'red':'green'}">${m.unit==='家'?(delta>0?'+':'')+money(delta):signed(v)}${m.unit==='家'?'家':m.kind==='rate'?'pp':'%'}</span>`}
function changes(m){return `<div class="metric-changes"><span>环比 ${comparison(m)}</span><span>${m.sameStore?'同店同比':'同比'} ${comparison(m,'yoy')}</span></div>`}
function metricCard(id,small=false){const m=metrics[id],v=current(m);return `<button class="group-metric ${small?'small':''}" data-go="${id}"><div class="metric-label">${m.name}<span>›</span></div><div class="metric-number ${m.color||''}">${fmt(v,m)}<small>${unit(m)}</small></div>${m.target!==undefined?`<div class="metric-hint">目标 ≥${m.target}${m.unit}</div>`:''}${changes(m)}</button>`}
function section(name,extra=''){return `<div class="section-title"><span>${name}</span><small>${extra}</small></div>`}
function dateTabs(){return `<div class="date-tabs" role="group" aria-label="日期类型">${[['day','日'],['week','周'],['month','月']].map(([id,n])=>`<button data-date-type="${id}" aria-pressed="${state.day===id}" class="${state.day===id?'selected':''}">${n}</button>`).join('')}</div>`}
function datePicker(){const r=dateRange(),year=r.start.slice(0,4),sameYear=year===r.end.slice(0,4),short=v=>v.slice(5).replace('-','.');const label=state.day==='month'?`${year}年${Number(r.start.slice(5,7))}月`:state.day==='week'?(sameYear?`<small>${year}年</small>${short(r.start)} – ${short(r.end)}`:`<small>${r.start.replaceAll('-','.')}</small>– ${r.end.replaceAll('-','.')}`):r.start.replaceAll('-','.');return `<button class="date-trigger" id="date-open" aria-label="选择统计日期" title="${rangeText(r)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5m10-5v5M3 11h18m-14 4h3m4 0h3m-10 3h3"/></svg><span class="date-copy">${label}</span><svg class="date-caret" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></button>`}
function filter(){return `<div class="hero date-only"><div class="date-filter">${dateTabs()}${datePicker()}</div></div>`}
function homeHeader(title){return `<section class="dashboard-hero" aria-label="集团概况"><div class="group-identity"><span class="group-mark" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="10" y="4" width="13" height="24" rx="2"/><path d="M10 15H6a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h4m13-15h3a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2h-3M14 9h5m-5 5h5m-5 5h5m-5 5h5"/></svg></span><div class="group-name"><h1>${title}</h1><p>多链互联餐饮集团</p></div></div><div class="group-badges" aria-label="集团规模"><span>6 大品牌</span><span>23 个城市</span><button data-go="stores" aria-label="${current(metrics.stores)}家在营门店，查看分析">${current(metrics.stores)} 家门店</button></div><div class="hero-periods">${dateTabs()}${datePicker()}</div></section>`}
function footer(){return '<footer class="footer">全部为模拟数据 · 点击指标可查看分析<br>金额与人数均为演示口径，不代表真实集团经营</footer>'}
function home(){return `${section('集团概览')}<div class="overview-block"><h2>门店</h2><div class="metric-grid">${metricCard('stores')}${metricCard('building')}</div><div class="ownership">${owners.map(([id,n,v])=>`<button data-go="${id}"><span>${n} ›</span><b>${v}<small>家</small></b></button>`).join('')}</div><button class="strip-metric" data-go="area"><span>坪效 ›<small>${state.day==='day'?'日':state.day==='week'?'周':'月'}坪效 · 按天数折算</small></span><div class="strip-reading"><b>${fmt(current(metrics.area),metrics.area)}<small>元/㎡</small></b>${changes(metrics.area)}</div></button></div><div class="overview-block"><h2>员工</h2><div class="metric-grid">${metricCard('fulltime')}${metricCard('hourly')}</div><div class="metric-grid one">${metricCard('efficiency')}</div></div><div class="overview-block"><h2>会员</h2><div class="metric-grid">${metricCard('members')}${metricCard('active')}</div><button class="strip-metric" data-go="activeRate"><span>活跃会员占比 ›<small>最近3个月有消费的会员</small></span><b>${fmt(current(metrics.activeRate),metrics.activeRate)}<small>%</small></b></button></div>${section('集团体检','四大核心能力')}<div class="health-grid">${['cash','sameStore','profitGrowth','opening'].map(id=>{const m=metrics[id];return `<button class="health-card" data-go="${id}"><div class="health-title"><i>${{cash:'▣',sameStore:'⌁',profitGrowth:'◴',opening:'↗'}[id]}</i><b>${m.name}</b><span>${m.caption}</span><em>›</em></div><div class="health-number ${current(m)<m.target?'orange':''}">${m.id==='profitGrowth'&&current(m)>0?'+':''}${fmt(current(m),m)}<small>${unit(m)}</small></div><div class="metric-hint">目标 ≥${m.target}${m.unit}</div>${changes(m)}</button>`}).join('')}</div>${section('巡店建议','利润 × 巡店得分')}<div class="quadrant-grid">${quadrants.slice(0,4).map(([id,name,n,desc,color])=>`<button class="quadrant" data-go="${id}"><div class="row"><b class="pill ${color}">${name}</b><strong class="${color}">${n}<small>家</small></strong></div><p>${desc}</p>${changes(metrics[id])}</button>`).join('')}</div><button class="pending-class" data-go="unrated">另有 197 家待评估，四类已评估合计 202 家<span>›</span></button>${section('门店实收')}<div class="card metric-grid">${metricCard('target')}${metricCard('receipt')}</div><div class="card card-pad"><button class="receipt-progress" data-go="attainment"><span>实收达成率 ›</span><b>${fmt(current(metrics.attainment),metrics.attainment)}%</b></button><div class="big-track"><div style="width:${current(metrics.attainment)}%;background:var(--blue)"></div></div><div class="explain">目标缺口 ¥ ${money(current(metrics.target)-current(metrics.receipt))}</div></div>${paymentChart()}${section('门店引流','7种方式 · 流量及占比')}<div class="card card-pad"><button class="receipt-progress" data-go="traffic"><span>已归因总流量 ›</span><b>${money(current(metrics.traffic))}<small>人次</small></b></button><div class="explain">最后有效触点归因 · 每次访问仅计入一个来源</div></div><div class="card">${attraction.map(([id,name,p],i)=>`<button class="flow-row" data-go="${id}"><div class="row"><span><i class="flow-index">${i+1}</i>${name} ›</span><b>${money(current(metrics[id]))}<small>${metrics[id].unit}</small></b></div><div class="flow-bottom"><div class="track"><div style="width:${p*100/.26}%"></div></div><span>${(p*100).toFixed(1)}%</span></div></button>`).join('')}</div>${section('门店损益','占实收比例 · 环比 · 同店同比')}<div class="card pnl">${['receipt',...costs.map(x=>x[0]),'profit'].map(id=>{const m=metrics[id];return `<button class="pnl-row ${id==='profit'?'profit-total':''}" data-go="${id}"><div class="row"><span>${id==='receipt'?'实收':m.name} ›</span><b>¥ ${money(current(m))}</b></div><div class="pnl-meta"><span>占实收 <b>${(current(m)/current(metrics.receipt)*100).toFixed(1)}%</b></span>${changes(m)}</div></button>`}).join('')}</div>${footer()}`}
const visits=[{market:'华南市场',store:'海滨示范店',priority:'优先巡查',color:'red',issue:'利润率 −2.3%，巡店得分 68 分',action:'重点核查食材耗用、损耗与当班操作。',owner:'区域督导 · 建议24小时内',metric:'problem'}, {market:'华东市场',store:'中心示范店',priority:'重点关注',color:'orange',issue:'利润率 15.2%，巡店得分 72 分',action:'核查卫生、服务及标准执行，预防利润下滑。',owner:'运营负责人 · 建议3日内',metric:'hidden'}, {market:'华中市场',store:'大学城示范店',priority:'经营辅导',color:'blue',issue:'利润率 5.1%，巡店得分 91 分',action:'复核商圈客流、商品结构和排班效率。',owner:'市场负责人 · 建议本周',metric:'potential'}];
function paymentChart(){const colors=['#2d62d7','#447af5','#6e99f9','#92b2fb','#abc7fb','#c6d9fd','#d4e5ff','#e3eeff','#f2f7ff'];let offset=0;const rings=payments.map(([id,n,p],i)=>{const x=`<circle cx="90" cy="90" r="68" fill="none" stroke="${colors[i]}" stroke-width="21" pathLength="100" stroke-dasharray="${p*100} ${100-p*100}" stroke-dashoffset="${-offset}" transform="rotate(-90 90 90)"/>`;offset+=p*100;return x}).join('');return `<div class="card card-pad"><div class="chart-title">支付类型分布</div><div class="donut-wrap"><svg viewBox="0 0 180 180" role="img" aria-label="支付类型分布，美团团购54.5%、抖音券21.3%、微信支付11.2%等"><g>${rings}</g><text x="90" y="82" text-anchor="middle" fill="#929baa" font-size="12">总计</text><text x="90" y="108" text-anchor="middle" fill="#263246" font-size="23" font-weight="600">${fmt(current(metrics.receipt),metrics.receipt)}${unit(metrics.receipt)}</text></svg></div><div class="payment-legend">${payments.map(([id,n,p],i)=>`<button data-go="${id}"><i style="background:${colors[i]}"></i><span>${n}</span><b>${(p*100).toFixed(1)}%</b><em>›</em></button>`).join('')}</div></div>`}
function attribution(m){const now=current(m),before=previous(m),delta=now-before;
if(m.base){const numerator=metrics[m.base],denominator=metrics[m.denominator],oldN=previous(numerator),newN=current(numerator),oldD=previous(denominator),newD=current(denominator);return {note:'比例＝分子÷分母。先替换分子，再替换分母，两项贡献相加等于比例变化。',rows:[[numerator.name+'变化',(newN-oldN)/oldD*100],[denominator.name+'变化',newN*(1/newD-1/oldD)*100]]}}
if(m.id==='receipt'){const d=days(),old=state.comparison==='mom'?{guests:2000,price:100,orders:2600,avg:50}:{guests:1836,price:100,orders:2400,avg:50};return {note:'连环替代法：先数量、后价格。堂食与外卖差额相加等于实收总差额；此为数学拆解，不代表已证实的经营原因。',rows:[['堂食客流',(1800-old.guests)*old.price*d],['堂食客单价',1800*(100-old.price)*d],['外卖订单数',(2500-old.orders)*old.avg*d],['外卖单均价',2500*(48-old.avg)*d]],equations:[['堂食客流',old.guests*d,1800*d,'人次'],['堂食客单价',old.price,100,'元'],['外卖订单数',old.orders*d,2500*d,'单'],['外卖单均价',old.avg,48,'元']]}}
if(m.id==='profit'){return {note:'实收增减减去各项成本费用增减，合计即预算利润变化。各项均按同一周期和同一门店集合比较。',rows:[['实收变化',current(metrics.receipt)-previous(metrics.receipt)],...costs.map(([id,n])=>[n+'变化',previous(metrics[id])-current(metrics[id])])]}}
if(costs.some(x=>x[0]===m.id)){const oldRevenue=previous(metrics.receipt),oldRate=before/oldRevenue;return {note:'成本/费用＝实收规模×费用率。先固定原费率测算规模影响，再计算费率变化影响；合计与本项金额差额一致。',rows:[['经营规模变化',(current(metrics.receipt)-oldRevenue)*oldRate],['单位成本/费率变化',current(metrics.receipt)*(now/current(metrics.receipt)-oldRate)]]}}
if(m.id==='attainment'){const oldReceipt=previous(metrics.receipt),oldTarget=oldReceipt/(before/100);return {note:'达成率＝实际实收÷目标实收。先替换实收，再替换目标；影响以百分点表示。',rows:[['实际实收变化',(current(metrics.receipt)-oldReceipt)/oldTarget*100],['目标实收变化',current(metrics.receipt)*(1/current(metrics.target)-1/oldTarget)*100]]}}
if(m.id==='efficiency'){const oldReceipt=previous(metrics.receipt),oldHours=oldReceipt/before,newHours=current(metrics.receipt)/now;return {note:'人效＝实收÷有效工时。先替换实收，再替换工时，量化两者对人效的影响。',rows:[['实收变化',(current(metrics.receipt)-oldReceipt)/oldHours],['有效工时变化',current(metrics.receipt)*(1/newHours-1/oldHours)]]}}
if(m.id==='activeRate'){const oldActive=previous(metrics.active),oldMembers=oldActive/(before/100),newActive=current(metrics.active);return {note:'活跃占比＝活跃会员÷累计会员。先替换分子，再替换分母，影响以百分点表示。',rows:[['活跃会员变化',(newActive-oldActive)/oldMembers*100],['累计会员变化',newActive*(1/current(metrics.members)-1/oldMembers)*100]]}}
const weights=m.drivers.length===2?[1.25,-.25]:m.drivers.length===3?[1.1,-.3,.2]:[.4,.2,.25,.15];const rows=m.drivers.map((n,i)=>[n,delta*weights[i]]);if(m.kind==='stock'&&m.unit!=='%'){rows.forEach(x=>x[1]=Math.round(x[1]));rows[rows.length-1][1]=delta-rows.slice(0,-1).reduce((n,x)=>n+x[1],0)}return {note:'演示贡献分解：各项影响相加等于指标净变化；贡献权重为模拟值，实际应用需用明细数据计算验证。',rows}}
function chart(m){const v=current(m),b=previous(m);const values=Array.from({length:7},(_,i)=>i===6?v:i===5?b:b+(v-b)*(i+1)/7+Math.sin(i*1.7)*Math.abs(v-b)*.22);const max=Math.max(...values),min=Math.min(...values),pad=Math.max((max-min)*.3,Math.abs(v)*.015,1),lo=min-pad,hi=max+pad;const pt=(n,i)=>[34+i*46,139-(n-lo)/(hi-lo)*108];const coords=values.map(pt);const labels=values.map((_,i)=>{if(state.day==='month'){const d=parseDate(dateRange().start);return iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-(6-i),1))).slice(0,7)}const step=state.day==='week'?7:1;return shiftDate(dateRange().end,-(6-i)*step).slice(5).replace('-','/')});const chosen=state.point===null?6:Math.max(0,Math.min(6,state.point));return `<div class="trend-readout"><span>${labels[chosen]} ${state.day==='day'?'日':state.day==='week'?'周':'月'}度示例</span><strong>${fmt(values[chosen],m,false)} <small>${m.unit}</small></strong></div><svg viewBox="0 0 340 171" class="chart" role="img" aria-label="${m.name}最近7个${state.day==='day'?'日':state.day==='week'?'周':'月'}度点趋势">${[0,1,2,3].map(i=>`<line x1="34" x2="316" y1="${31+i*36}" y2="${31+i*36}" stroke="#e6ecf5" stroke-dasharray="3 3"/><text x="28" y="${35+i*36}" text-anchor="end" class="chart-label">${Math.abs(hi)>10000?((hi-(hi-lo)*i/3)/10000).toFixed(1)+'万':(hi-(hi-lo)*i/3).toFixed(m.decimals)}</text>`).join('')}<polyline points="${coords.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#4b89f6" stroke-width="2.2"/>${coords.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${i===chosen?4:2.5}" fill="#4b89f6" stroke="white"/>`).join('')}${labels.map((l,i)=>`<text x="${34+i*46}" y="163" text-anchor="middle" class="chart-label">${l}</text>`).join('')}</svg><div class="chart-points" aria-label="查看趋势点">${labels.map((l,i)=>`<button data-point="${i}" class="${i===chosen?'active':''}">${l}</button>`).join('')}</div><div class="explain">最近7个${state.day==='day'?'日':state.day==='week'?'周':'月'}度示例点 · 点击日期查看数值</div>`}
function ranking(m){const v=current(m),additive=m.unit==='元'||m.unit==='人'||m.unit==='人次'||m.unit==='单'||m.unit==='家'||m.unit==='人天';const shares=[.28,.22,.18,.14,.11,.07];let vals;if(additive){vals=shares.map(p=>m.unit==='家'||m.unit==='人'||m.unit==='单'?Math.floor(v*p):v*p);vals[5]=v-vals.slice(0,5).reduce((a,b)=>a+b,0)}else vals=[1.1,.95,1.05,.9,1.08,.92].map(p=>v<0?v+(p-1)*10:v*p);if(m.base){const baseMetric=metrics[m.base],denMetric=metrics[m.denominator];if(costs.some(x=>x[0]===m.base)){const adjustment=[1.1,.95,1.05,.9,1.08,.92],mean=shares.reduce((n,p,i)=>n+p*adjustment[i],0);vals=shares.map((p,i)=>current(baseMetric)*p*adjustment[i]/mean/(current(denMetric)*p)*100)}}else if(costs.some(x=>x[0]===m.id)){const adjustment=[1.1,.95,1.05,.9,1.08,.92],mean=shares.reduce((n,p,i)=>n+p*adjustment[i],0);vals=shares.map((p,i)=>v*p*adjustment[i]/mean)}const rows=regions.map((name,i)=>({name,value:vals[i]})).sort((a,b)=>m.lower?a.value-b.value:b.value-a.value);const max=Math.max(...vals.map(Math.abs),1);return `<div class="ranking-note">集团内部区域市场 · ${additive?'各市场合计与集团值一致':'同一指标口径对比，不可相加'} · 模拟</div>${rows.map((r,i)=>`<div class="market-row"><div class="row"><span><i>${i+1}</i>${r.name}</span><b>${fmt(r.value,m,false)}<small>${m.unit}</small></b></div><div class="track"><div style="width:${Math.abs(r.value)/max*100}%"></div></div></div>`).join('')}`}
function detail(id){const m=metrics[id],v=current(m),b=previous(m),delta=v-b,a=attribution(m);const deltaUnit=m.kind==='rate'?'个百分点':m.unit;return `${filter()}<div class="detail-context">集团汇总 <span>${rangeText(dateRange())}</span></div><div class="card card-pad">${m.base||m.shareMetric?`<div class="tabs"><button data-go="${m.base||m.id}" class="${m.base?'':'active'}">${m.unit==='单'||(m.base&&metrics[m.base].unit==='单')?'订单量':m.unit==='人次'||(m.base&&metrics[m.base].unit==='人次')?'流量':'金额'}</button><button data-go="${m.base?m.id:m.shareMetric}" class="${m.base?'active':''}">占比</button></div>`:''}<div class="metric-label">${m.name}</div><div class="detail-value">${fmt(v,m)}<small>${unit(m)}</small></div>${changes(m)}${m.share!==undefined?`<div class="metric-hint">${costs.some(x=>x[0]===m.id)?'占实收':payments.some(x=>x[0]===m.id)?'支付占比':'流量占比'} ${(m.share*100).toFixed(1)}%</div>`:''}<div class="definition">${m.formula}</div></div>${section('01 指标趋势')}<div class="card card-pad">${chart(m)}</div>${section('02 量化归因分析')}<div class="card card-pad"><div class="tabs"><button data-compare="mom" class="${state.comparison==='mom'?'active':''}">环比</button><button data-compare="yoy" class="${state.comparison==='yoy'?'active':''}">${m.sameStore?'同店同比':'同比'}</button></div><div class="explain">对比期：${rangeText(compareRange())}</div><div class="bridge-summary"><div><span>对比期</span><b>${fmt(b,m,false)}</b></div><em>→</em><div><span>本期</span><b>${fmt(v,m,false)}</b></div><div><span>净变化 / ${deltaUnit}</span><b class="${delta<0?'red':'green'}">${delta>0?'+':''}${fmt(delta,m,false)}</b></div></div><div class="explain">${a.note} 显示值四舍五入，可能存在尾差。</div></div><div class="card">${a.rows.map(([name,n])=>`<div class="contribution-row"><div class="row"><span>${name}</span><b class="${n<0?'red':'green'}">${n>0?'+':''}${fmt(n,m,false)}<small>${deltaUnit}</small></b></div><div class="contribution-bar"><span style="width:${Math.min(100,Math.abs(n)/(Math.max(...a.rows.map(x=>Math.abs(x[1])))||1)*100)}%;background:${n<0?'#f16a77':'#51bc9b'}"></span></div></div>`).join('')}<div class="contribution-total">贡献合计 <b>${delta>0?'+':''}${fmt(a.rows.reduce((n,x)=>n+x[1],0),m,false)} ${deltaUnit}</b></div></div>${a.equations?`<div class="card table-wrap"><table><thead><tr><th>实收驱动因子</th><th>对比期</th><th>本期</th></tr></thead><tbody>${a.equations.map(([n,b,v,u])=>`<tr><td>${n} / ${u}</td><td>${money(b)}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table><div class="card-pad explain">堂食：${money(1800*days())}人次 × 100元 = ${money(flow(180000))}元<br>外卖：${money(2500*days())}单 × 48元 = ${money(flow(120000))}元</div></div>`:''}${section('03 市场排行',m.lower?'由低到高':'由高到低')}<div class="card card-pad">${ranking(m)}</div><button class="back-home" data-go="home">返回集团看板</button>${footer()}`}
function visitDetail(index){const v=visits[index]||visits[0];return `${filter()}<div class="card card-pad"><div class="row"><h2 class="visit-heading">${v.store}</h2><span class="pill ${v.color}">${v.priority}</span></div><p class="minor muted">${v.market} · ${v.owner}</p><p class="minor">${v.issue}</p></div>${section('巡店重点')}<div class="card card-pad"><p class="minor">${v.action}</p><ol class="visit-checklist"><li>核对异常指标的原始凭证、班次和统计口径。</li><li>现场确认原因，记录证据与负责岗位。</li><li>约定整改时限，复查同口径指标及执行结果。</li></ol></div>${section('量化依据')}<div class="card">${metricCard(v.metric)}${metricCard('profit')}${metricCard('food')}</div><div class="notice">该门店案例为模拟。下方指标穿透为集团口径，用于展示趋势、归因与区域排行流程。</div><button class="back-home" data-go="${v.metric}">查看${metrics[v.metric].name}趋势、归因与排行 ›</button>${footer()}`}
function dialogs(){return `<dialog id="date-dialog"><form id="date-form"><h3>选择${state.day==='month'?'月份':state.day==='week'?'周':'日期'}</h3><input id="date-input" aria-label="统计日期" type="${state.day==='month'?'month':'date'}" value="${state.day==='month'?state.date.slice(0,7):state.date}" min="${state.day==='month'?'2020-01':'2020-01-01'}" max="${state.day==='month'?'2035-12':'2035-12-31'}" required><p>${state.day==='week'?'选择周内任意一天，自动按周一至周日统计。':state.day==='month'?'按自然月统计。':'起止日期均为所选当天。'}所有数据为演示。</p><div class="date-actions"><button type="button" id="date-cancel">取消</button><button type="submit">确定</button></div></form></dialog>`}
function render(){if(!['day','week','month'].includes(state.day))state.day='day';if(!validDate(state.date))state.date='2026-09-18';const id=route(),isMetric=!!metrics[id],isVisit=id.startsWith('visit-'),isHome=!isMetric&&!isVisit;const title=isHome?'老板看板':isMetric?metrics[id].name:'巡店建议';document.title=title+' · 集团演示';document.getElementById('app').classList.toggle('home-view',isHome);document.getElementById('app').innerHTML=(isHome?homeHeader(title):`<header><button id="back" aria-label="返回上一页">‹</button><h1>${title}</h1><span class="demo">DEMO</span></header>`)+(isHome?home():isMetric?detail(id):visitDetail(Number(id.slice(6))))+dialogs();document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>go(e.dataset.go));document.querySelectorAll('[data-date-type]').forEach(e=>e.onclick=()=>{state.day=e.dataset.dateType;state.point=null;persist();render()});document.querySelectorAll('[data-compare]').forEach(e=>e.onclick=()=>{state.comparison=e.dataset.compare;persist();render()});document.querySelectorAll('[data-point]').forEach(e=>e.onclick=()=>{state.point=Number(e.dataset.point);render()});document.getElementById('date-open').onclick=()=>document.getElementById('date-dialog').showModal();document.getElementById('date-cancel').onclick=()=>document.getElementById('date-dialog').close();document.getElementById('date-form').onsubmit=e=>{e.preventDefault();const v=document.getElementById('date-input').value,selected=state.day==='month'?v+'-01':v;if(validDate(selected)){state.date=selected;state.point=null;persist();render()}};const back=document.getElementById('back');if(back)back.onclick=()=>history.state?.depth>0?history.back():go('home')}
history.scrollRestoration='manual';if(history.state?.filters)Object.assign(state,history.state.filters);window.addEventListener('popstate',()=>{if(history.state?.filters)Object.assign(state,history.state.filters);render();window.scrollTo(0,history.state?.scroll||0)});render();persist();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_dashboard_filters',description:'切换集团看板的日期类型与日期，所有指标同步展示。',inputSchema:{type:'object',properties:{day:{type:'string',enum:['day','week','month']},date:{type:'string'}},required:['day','date'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!['day','week','month'].includes(input.day)||!validDate(input.date))throw Error('日期无效');Object.assign(state,{day:input.day,date:input.date,point:null});persist();render();return {range:dateRange(),simulated:true}}})).catch(()=>{});}catch{}}
